import pytest

from formula import formula_from_smiles


@pytest.mark.parametrize(
    "smiles,expected_formula,expected_mass",
    [
        ("CCO", "C2H6O", 46.069),
        ("C=O", "CH2O", 30.026),
        ("C#N", "CHN", 27.026),
        ("C1CCCCC1", "C6H12", 84.162),
        ("ClC(Cl)Cl", "CHCl3", 119.369),
    ],
)
def test_known_answers(smiles, expected_formula, expected_mass):
    formula, mass = formula_from_smiles(smiles)
    assert formula == expected_formula
    assert abs(mass - expected_mass) <= 0.001


@pytest.mark.parametrize("smiles", ["C1CC", "C1CCC2CCCC2", "CC(C"])
def test_invalid_raises(smiles):
    with pytest.raises(ValueError):
        formula_from_smiles(smiles)
